import{_ as o}from"./chunks/settings-robot.pc.ko.CimpdZDI.js";import{_ as d,o as c,c as t,a5 as a}from"./chunks/framework.D47SInms.js";const r="/RBQ/nightly/images/app/settings-app.pc.ko.png",_=JSON.parse('{"title":"설정","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/settings.md","filePath":"ko/manual/gui/settings.md","lastUpdated":1791600043000}'),l={name:"ko/manual/gui/settings.md"};function i(n,e,p,s,h,m){return c(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h1><p>허브의 <code>설정</code> 타일로 엽니다. 섹션은 모두 화면 위쪽에 칩으로 늘어서고(폰에서는 아이콘만) 두 묶음으로 나뉩니다. 제목은 <code>설정</code>이고, 로봇 이름·시리얼과 기기·앱 버전이 함께 표시됩니다.</p><ul><li><strong>로봇 섹션</strong>은 고른 로봇에 딸린 설정입니다: <code>전원 제어</code>, <code>페이로드 설정</code>. 로봇이 없어도 열 수 있지만, 로봇에 닿는 동작은 로봇이 연결돼 있어야 됩니다. 앱 내 시뮬레이터를 고른 동안에는 흐리게 표시됩니다.</li><li><strong>앱 섹션</strong>은 이 기기에 딸린 설정입니다: <code>게임패드</code>, <code>앱 설정</code>. 언제나 열립니다.</li></ul><p>설정 화면 왼쪽 위의 로고를 누르면 허브로 돌아가고, 그 옆 게임패드 버튼을 누르면 곧바로 제어 화면으로 갑니다. 이 버튼은 로봇이 연결됐거나 시뮬을 켠 동안에만 눌립니다.</p><ul><li>로봇 연결은 허브의 로봇 목록에서 합니다. <a href="/RBQ/nightly/ko/manual/gui/connection.html">연결</a>을 참고하세요.</li><li><code>게임패드</code>는 <a href="/RBQ/nightly/ko/manual/gui/gamepad.html">게임패드</a>에서 다룹니다.</li><li><code>캘리브레이션</code>, <code>로봇 점검</code>, <code>소프트웨어 업데이트</code>는 <a href="/RBQ/nightly/ko/manual/gui/maintenance.html">정비</a> 화면에 있습니다.</li></ul><p>이 페이지는 <code>전원 제어</code>, <code>페이로드 설정</code>, <code>앱 설정</code>을 설명합니다. 모두 운용자가 사용할 수 있으며, 개발자 모드가 필요한 항목은 따로 표시했습니다.</p><h2 id="power" tabindex="-1">전원 제어 <a class="header-anchor" href="#power" aria-label="Permalink to &quot;전원 제어 {#power}&quot;">​</a></h2><p>일상 운용에서 켜고 끄는 보조 전원을 다룹니다. 토글은 로봇이 보고한 실제 PDU 상태를 그대로 보여 줍니다. 그래서 눌러도 화면에 반영되기까지 1초쯤 걸릴 수 있습니다. 레일 상태가 처음 들어오기 전에는 토글이 꺼진 채로 있습니다.</p><p><strong>12 V 토글</strong>(한 번 탭): <code>스피커 앰프 (12V)</code>, <code>CCTV (12V)</code>, <code>열화상 (12V)</code>, <code>IR LED (12V)</code>.</p><p><strong>48 V 레일</strong>(2단계): <code>ARM · ADDON (48V)</code>, <code>EXTERN (48V)</code> 각각 현재 전압과 <code>끄기</code> / <code>켜기</code> 버튼이 있습니다. 누르면 <code>정말 끌까요?</code> / <code>정말 켤까요?</code>가 뜨고, 확정하면 전환됩니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>ARM · ADDON (48V)</code>는 팔과 애드온이 PDU 포트 하나를 함께 씁니다. 이 레일을 끄면 팔 전원도 함께 나가므로 팔이 정지 상태인지 먼저 확인하세요.</p></div><p>카메라·통신·Vision PC·LEGS(48 V) 전원, LiDAR, 시스템 재부팅은 여기 없습니다. 끄면 연결이 끊기거나 로봇이 주저앉는 조작이라 <a href="/RBQ/nightly/ko/manual/gui/maintenance.html">정비</a>(개발자 모드)에 있습니다.</p><p>CAN-FD 기체에서는 이 섹션이 레일 대신 포트 단위로 나옵니다: <code>CCTV (12V · LAN2)</code>, <code>열화상 · PTZ (12V · LAN3)</code>, <code>전방 12V (IR LED)</code>, <code>후방 12V (IR LED)</code>, <code>스피커 앰프</code>(한 번 탭)와 <code>ARM · ADDON (48V)</code>(2단계). 각 행에 실측 상태·전압·전류가 표시되고, 포트 상태를 받기 전에는 행이 잠깁니다.</p><p>CAN-FD 기체에는 <code>하단 상태 LED (IF 보드)</code> 묶음도 있습니다. 몸체 아래 상태 LED 두 개가 <code>오른쪽 LED</code>, <code>왼쪽 LED</code> 한 줄씩 나오고, 줄마다 지금 설정과 소비 전력(W), 실제로 나가는 색이 보입니다. <code>설정</code>을 누르면 로봇이 알려 준 값으로 채워진 창이 뜹니다. <code>추천 설정</code>에서 <code>꺼 두기</code>나 RBQ에 쓰기로 정한 값을 고르면 되고, 창에 <code>지금 설정</code>도 함께 나옵니다. <code>반대쪽 LED에도 같은 값 적용</code>을 켜면 두 LED를 한 번에 바꿉니다. <code>적용</code>을 누르면 설정을 보낸 뒤 로봇에서 다시 읽어 확인합니다. <code>적용했습니다 — 로봇 값과 일치합니다</code>가 뜨면 LED가 받은 것입니다. <code>다시 읽기</code>는 로봇의 값으로 창을 다시 채웁니다.</p><p>LED 전력은 IF 보드가 스스로 제한합니다(순간 20 W, 지속 10.5 W). 그래서 밝게 설정하면 넣은 값보다 어둡게 나올 수 있고, 그때 줄에 <code>제한 중</code>이 뜹니다. 로봇에서 값을 읽지 못하면 <code>읽지 못함</code>과 함께 이 기기가 마지막으로 읽었거나 보낸 값을 보여 줍니다. IF 보드가 재부팅한 직후에는 설정이 들어올 때까지 <code>설정 없음 — IF가 재부팅한 뒤 아직 설정을 받지 못했습니다</code>로 나옵니다. 로봇 소프트웨어가 이 기능보다 오래됐으면 줄에 <code>로봇 소프트웨어에 이 기능이 없습니다. 업데이트가 필요합니다</code>가 뜹니다. IF 보드 펌웨어가 오래됐으면 줄에 지금 버전과 필요한 버전이 함께 나오고(예: <code>IF 펌웨어 업데이트가 필요합니다 — 지금 261003, 261005 이상이어야 합니다</code>), 보드를 업데이트할 때까지 <code>적용</code>이 잠깁니다.</p><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#what-changes">개발자 모드</a>에 모아 두었습니다.</p></blockquote><h2 id="robot-parameters" tabindex="-1">페이로드 설정 <a class="header-anchor" href="#robot-parameters" aria-label="Permalink to &quot;페이로드 설정 {#robot-parameters}&quot;">​</a></h2><p><img src="'+o+'" alt="로봇 파라미터 섹션"></p><p><code>로봇 페이로드 설정</code>에는 로봇에 실은 적재물을 적어 둡니다. 이 값이 보행 동역학에 반영됩니다.</p><ol><li>로봇은 13개의 페이로드 슬롯을 보고합니다. 슬롯을 체크해 장착으로 표시하고 질량과 무게중심(X, Y, Z)을 입력합니다.</li><li>하단에 합계 질량과 합성 무게중심이 표시되며, 합계가 상한을 넘으면 경고합니다.</li><li><code>Set Payload</code>를 누르고 <code>적용</code>으로 확정합니다(<code>Get</code>은 로봇의 슬롯을 다시 읽어 편집 내용을 버립니다). 확인 창에 장착 슬롯 수와 합계가 표시되고, 체크 해제한 슬롯은 질량 0으로 전송됩니다. 새 값은 즉시 보행 동역학에 반영되며 1~2초에 걸쳐 천천히 적용됩니다.</li></ol><p><code>도움말</code>을 누르면 표 위에 짧은 안내가 펼쳐집니다. 페이로드 슬롯 API가 없는 로봇에서는 로봇 소프트웨어 갱신을 안내하는 문구가 대신 표시됩니다.</p><h2 id="앱-설정" tabindex="-1">앱 설정 <a class="header-anchor" href="#앱-설정" aria-label="Permalink to &quot;앱 설정&quot;">​</a></h2><p><img src="'+r+'" alt="앱 설정 섹션"></p><p>로봇이 아니라 앱 자체의 환경설정입니다.</p><table tabindex="0"><thead><tr><th>행</th><th>옵션</th></tr></thead><tbody><tr><td><code>테마</code></td><td><code>다크</code> / <code>라이트</code></td></tr><tr><td><code>언어 / Language</code></td><td><code>한국어</code> / <code>English</code> — 즉시 적용</td></tr><tr><td><code>조이스틱 감도</code></td><td>슬라이더 — 입력 응답 곡선</td></tr><tr><td><code>화면 항상 켜기</code></td><td>토글 — 제어 중 화면 유지</td></tr><tr><td><code>데드존</code></td><td>슬라이더 — 조이스틱 중심 무시 범위</td></tr><tr><td><code>Gyro 위젯</code></td><td>토글 — 롤/피치 자세계 표시</td></tr><tr><td><code>전체화면</code></td><td>토글 — 브라우저 전용</td></tr><tr><td><code>저신호 경고</code></td><td>토글 — Wi-Fi 신호가 <code>경고 임계</code>(<code>Warning threshold</code>, 켜져 있을 때 표시되는 슬라이더) 미만이면 상단 경고 배너</td></tr><tr><td><code>경고 비프 (Notify BEEP)</code></td><td>토글 — 경고 시 짧은 알림음(웹 전용)</td></tr><tr><td><code>배터리 부족 경고음</code></td><td>토글 — 로봇 배터리가 부족하면 알림음. <code>경고 비프 (Notify BEEP)</code>가 켜져 있어야 합니다(웹 전용)</td></tr><tr><td><code>UI 배율</code></td><td>데스크탑 앱 전용 — <code>자동</code>, 100 %~200 %</td></tr></tbody></table><h3 id="developer-mode" tabindex="-1">개발자 모드 <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;개발자 모드 {#developer-mode}&quot;">​</a></h3><p><code>개발자 모드</code> 토글은 오른쪽 위 둥근 버튼을 누르면 나오는 프로필 메뉴에 있습니다. 게스트 상태에서는 <code>개발자 모드</code>를 켜고 암호를 넣으면 됩니다. 다시 끄면 운용자 레벨로 돌아갑니다. 접근 코드로 로그인한 동안(같은 메뉴의 <code>접근 코드로 로그인</code>)에는 계정이 레벨을 결정하므로 토글이 나오지 않습니다.</p><p>개발자 모드를 켜면 <code>정비</code>의 개발자 섹션, 위의 개발자 전용 행, <code>모션 선택</code> 그리드의 <code>포지션 제어</code> 그룹이 추가됩니다.</p>',28)])])}const D=d(l,[["render",i]]);export{_ as __pageData,D as default};
